import { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

const BlogList = () => {
  const [blogs, setBlogs] = useState([]);

  useEffect(() => {
    const fetchBlogs = async () => {
      const res = await axios.get('http://localhost:8080/api/blogs');
      setBlogs(res.data);
    };
    fetchBlogs();
  }, []);

  const handleDelete = async (id) => {
    await axios.delete(`http://localhost:8080/api/blogs/${id}`);
    setBlogs(blogs.filter(blog => blog.id !== id));
  };

  return (
    <div>
      {blogs.map((blog) => (
        <div key={blog.id} className="border p-4 mb-2">
          <h2 className="text-xl font-bold">{blog.title}</h2>
          <p>{blog.content}</p>
          <Link to={`/blogs/${blog.id}`} className="text-blue-500">View Details</Link>
          <button onClick={() => handleDelete(blog.id)} className="bg-red-500 text-white ml-2 p-1">Delete</button>
        </div>
      ))}
    </div>
  );
};

export default BlogList;
